// Package summaries runs the daily book summary plan: one book a day, in a fixed order, with a
// detailed summary (about 5,000 words) generated by the Claude API and read on the Kindle.
//
// Day N of the plan (counted from start_date) shows the book at position N. The plan is
// loaded once from data/books/summaries.yaml and edited on the web dashboard afterwards.
package summaries

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"strings"
	"sync"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/shyam/dashboard/internal/llm"
)

/* ---------- types ---------- */

// Settings steer the plan and the summaries. Stored in kv book_summaries.
type Settings struct {
	StartDate  string            `json:"start_date"`
	Words      int               `json:"words"`
	Style      string            `json:"style"`
	Language   string            `json:"language"`
	Priority   string            `json:"priority"`
	Reader     string            `json:"reader"`
	Categories map[string]string `json:"categories"` // category -> goal
}

// Book is one entry in the plan, with the state of its summary.
type Book struct {
	ID       int        `json:"id"`
	Position int        `json:"position"`
	Title    string     `json:"title"`
	Author   string     `json:"author"`
	Category string     `json:"category"`
	Why      string     `json:"why"`
	Date     string     `json:"date"`             // the day this book is scheduled for
	Status   string     `json:"status"`           // pending | ready | error
	ReadAt   *time.Time `json:"readAt,omitempty"` // when you marked it read
	Rating   int        `json:"rating,omitempty"`
	Note     string     `json:"note,omitempty"`
	Words    int        `json:"words,omitempty"`
}

func (b Book) Read() bool { return b.ReadAt != nil }

type Intro struct {
	OneLine     string `json:"oneLine"`     // the book in one sentence
	AuthorAim   string `json:"authorAim"`   // what the author is trying to teach
	AboutAuthor string `json:"aboutAuthor"` // who wrote it and why they are credible
	BigIdea     string `json:"bigIdea"`     // the central argument, a few paragraphs
	WhoFor      string `json:"whoFor"`      // why it matters for you
}

type Lesson struct {
	Title    string `json:"title"`
	Idea     string `json:"idea"`     // the concept explained, paragraphs
	AtWork   string `json:"atWork"`   // example from work / software engineering
	InLife   string `json:"inLife"`   // example from everyday life in India
	Remember string `json:"remember"` // one line to keep
}

type Insight struct {
	Title       string `json:"title"`
	Explanation string `json:"explanation"`
	Evidence    string `json:"evidence"` // established research | mixed evidence | author's framework | contested
	Source      string `json:"source"`   // studies, researchers or traditions behind it
}

type Exercise struct {
	Title string   `json:"title"`
	Why   string   `json:"why"`
	Steps []string `json:"steps"`
	When  string   `json:"when"` // when and how often
}

// Summary is the generated text, in the six-part format.
type Summary struct {
	Intro       Intro      `json:"intro"`
	Lessons     []Lesson   `json:"lessons"`
	Insights    []Insight  `json:"insights"`
	Exercises   []Exercise `json:"exercises"`
	Limits      string     `json:"limits"`      // where the book is weak, dated or contested
	Connections []string   `json:"connections"` // links to books earlier in the plan
	Takeaways   []string   `json:"takeaways"`
	FinalThought string    `json:"finalThought"`
	WordCount   int        `json:"wordCount"`
	Minutes     int        `json:"minutes"`
}

// Entry is a book with its summary.
type Entry struct {
	Book
	Summary     *Summary  `json:"summary,omitempty"`
	Model       string    `json:"model,omitempty"`
	Error       string    `json:"error,omitempty"`
	GeneratedAt time.Time `json:"generatedAt,omitempty"`
}

// Status is what the Kindle snapshot carries under practice.reading.summary.
type Status struct {
	Started   bool   `json:"started"`
	Day       int    `json:"day"`   // plan day (1 = first book)
	Total     int    `json:"total"` // books in the plan
	StartDate string `json:"startDate"`
	Finished  bool   `json:"finished"` // past the last book: add more on the dashboard
	Today     *Entry `json:"today,omitempty"`
	Next      []Book `json:"next"`
	ReadCount int    `json:"readCount"`
	Generator string `json:"generator"` // live | not configured
}

/* ---------- service ---------- */

type Service struct {
	pool *pgxpool.Pool
	llm  *llm.Client
	tz   *time.Location
	mu   sync.Mutex
}

func New(pool *pgxpool.Pool, client *llm.Client, tz *time.Location) *Service {
	return &Service{pool: pool, llm: client, tz: tz}
}

func (s *Service) Configured() bool { return s.llm.Configured() }

func (s *Service) Today() time.Time {
	n := time.Now().In(s.tz)
	return time.Date(n.Year(), n.Month(), n.Day(), 0, 0, 0, 0, s.tz)
}

func (s *Service) Settings(ctx context.Context) Settings {
	st := Settings{Words: 5000}
	var raw []byte
	if err := s.pool.QueryRow(ctx, `SELECT value FROM kv WHERE key='book_summaries'`).Scan(&raw); err == nil {
		_ = json.Unmarshal(raw, &st)
	}
	if st.StartDate == "" {
		st.StartDate = s.Today().Format("2006-01-02")
	}
	if st.Words < 1500 || st.Words > 9000 {
		st.Words = 5000
	}
	return st
}

func (s *Service) SaveSettings(ctx context.Context, st Settings) error {
	if _, err := time.Parse("2006-01-02", st.StartDate); err != nil {
		return errors.New("start date must be YYYY-MM-DD")
	}
	if st.Words < 1500 || st.Words > 9000 {
		return errors.New("summary length must be 1,500 to 9,000 words")
	}
	old := s.Settings(ctx)
	if st.Categories == nil {
		st.Categories = old.Categories
	}
	raw, _ := json.Marshal(st)
	_, err := s.pool.Exec(ctx, `INSERT INTO kv(key,value,updated_at) VALUES('book_summaries',$1,now()) ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, updated_at=now()`, raw)
	return err
}

func (s *Service) start(ctx context.Context) time.Time {
	t, err := time.ParseInLocation("2006-01-02", s.Settings(ctx).StartDate, s.tz)
	if err != nil {
		return s.Today()
	}
	return t
}

// DayFor returns the plan day for a date (1 = start date, 0 or less = before the start).
func (s *Service) DayFor(ctx context.Context, date time.Time) int {
	st := s.start(ctx)
	return int(date.Sub(st).Hours()/24+0.5) + 1
}

// DateOf returns the scheduled date of a plan position.
func (s *Service) DateOf(ctx context.Context, position int) time.Time {
	return s.start(ctx).AddDate(0, 0, position-1)
}

/* ---------- plan reads ---------- */

const bookCols = `b.id, b.position, b.title, b.author, b.category, b.why,
	coalesce(s.status,'pending'), s.read_at, coalesce(s.rating,0), coalesce(s.note,''), coalesce((s.summary->>'wordCount')::int,0)`

func scanBook(row pgx.Row, b *Book) error {
	return row.Scan(&b.ID, &b.Position, &b.Title, &b.Author, &b.Category, &b.Why, &b.Status, &b.ReadAt, &b.Rating, &b.Note, &b.Words)
}

// Plan returns every book in order with the state of its summary.
func (s *Service) Plan(ctx context.Context) ([]Book, error) {
	rows, err := s.pool.Query(ctx, `SELECT `+bookCols+` FROM book_plan b LEFT JOIN book_summaries s ON s.book_id=b.id ORDER BY b.position`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	start := s.start(ctx)
	var out []Book
	for rows.Next() {
		var b Book
		if err := scanBook(rows, &b); err != nil {
			return nil, err
		}
		b.Date = start.AddDate(0, 0, b.Position-1).Format("2006-01-02")
		out = append(out, b)
	}
	return out, rows.Err()
}

func (s *Service) book(ctx context.Context, where string, arg any) (*Book, error) {
	var b Book
	if err := scanBook(s.pool.QueryRow(ctx, `SELECT `+bookCols+` FROM book_plan b LEFT JOIN book_summaries s ON s.book_id=b.id WHERE `+where, arg), &b); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, errors.New("no such book")
		}
		return nil, err
	}
	b.Date = s.DateOf(ctx, b.Position).Format("2006-01-02")
	return &b, nil
}

func (s *Service) BookByID(ctx context.Context, id int) (*Book, error) {
	return s.book(ctx, "b.id=$1", id)
}

func (s *Service) BookAt(ctx context.Context, position int) (*Book, error) {
	return s.book(ctx, "b.position=$1", position)
}

// Get returns a book with its summary (Summary is nil while pending).
func (s *Service) Get(ctx context.Context, id int) (*Entry, error) {
	b, err := s.BookByID(ctx, id)
	if err != nil {
		return nil, err
	}
	e := &Entry{Book: *b}
	var raw []byte
	err = s.pool.QueryRow(ctx, `SELECT summary, model, error, generated_at FROM book_summaries WHERE book_id=$1`, id).Scan(&raw, &e.Model, &e.Error, &e.GeneratedAt)
	if err == nil && b.Status == "ready" {
		var sm Summary
		if json.Unmarshal(raw, &sm) == nil {
			e.Summary = &sm
		}
	}
	return e, nil
}

// StatusFor builds the Kindle view for a date.
func (s *Service) StatusFor(ctx context.Context, date time.Time) *Status {
	st := &Status{Next: []Book{}, StartDate: s.Settings(ctx).StartDate, Generator: "not configured"}
	if s.Configured() {
		st.Generator = "live"
	}
	_ = s.pool.QueryRow(ctx, `SELECT count(*) FROM book_plan`).Scan(&st.Total)
	_ = s.pool.QueryRow(ctx, `SELECT count(*) FROM book_summaries WHERE read_at IS NOT NULL`).Scan(&st.ReadCount)
	st.Day = s.DayFor(ctx, date)
	st.Started = st.Day >= 1
	st.Finished = st.Day > st.Total
	if st.Started && !st.Finished {
		if b, err := s.BookAt(ctx, st.Day); err == nil {
			st.Today, _ = s.Get(ctx, b.ID)
		}
	}
	from := st.Day + 1
	if from < 1 {
		from = 1
	}
	rows, err := s.pool.Query(ctx, `SELECT `+bookCols+` FROM book_plan b LEFT JOIN book_summaries s ON s.book_id=b.id WHERE b.position >= $1 ORDER BY b.position LIMIT 3`, from)
	if err == nil {
		for rows.Next() {
			var b Book
			if scanBook(rows, &b) == nil {
				b.Date = s.DateOf(ctx, b.Position).Format("2006-01-02")
				st.Next = append(st.Next, b)
			}
		}
		rows.Close()
	}
	return st
}

/* ---------- plan writes ---------- */

// AddBook appends a book at the end of the plan.
func (s *Service) AddBook(ctx context.Context, b Book) error {
	if strings.TrimSpace(b.Title) == "" {
		return errors.New("title is required")
	}
	_, err := s.pool.Exec(ctx, `INSERT INTO book_plan(position,title,author,category,why) VALUES((SELECT coalesce(max(position),0)+1 FROM book_plan),$1,$2,$3,$4)`,
		strings.TrimSpace(b.Title), strings.TrimSpace(b.Author), strings.TrimSpace(b.Category), strings.TrimSpace(b.Why))
	return err
}

// UpdateBook edits the text of a book. Its summary is kept; regenerate it if the title changed.
func (s *Service) UpdateBook(ctx context.Context, b Book) error {
	if strings.TrimSpace(b.Title) == "" {
		return errors.New("title is required")
	}
	tag, err := s.pool.Exec(ctx, `UPDATE book_plan SET title=$2, author=$3, category=$4, why=$5 WHERE id=$1`,
		b.ID, strings.TrimSpace(b.Title), strings.TrimSpace(b.Author), strings.TrimSpace(b.Category), strings.TrimSpace(b.Why))
	if err == nil && tag.RowsAffected() == 0 {
		err = errors.New("no such book")
	}
	return err
}

// DeleteBook removes a book that has not been read and closes the gap, so later books move a day earlier.
func (s *Service) DeleteBook(ctx context.Context, id int) error {
	b, err := s.BookByID(ctx, id)
	if err != nil {
		return err
	}
	if b.Read() {
		return errors.New("this book is marked read; it stays in the plan as history")
	}
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)
	if _, err := tx.Exec(ctx, `DELETE FROM book_plan WHERE id=$1`, id); err != nil {
		return err
	}
	if _, err := tx.Exec(ctx, `UPDATE book_plan SET position=position-1 WHERE position > $1`, b.Position); err != nil {
		return err
	}
	return tx.Commit(ctx)
}

// Move shifts a book one place up (-1) or down (+1), swapping it with its neighbour.
func (s *Service) Move(ctx context.Context, id, delta int) error {
	if delta != -1 && delta != 1 {
		return errors.New("move by one place at a time")
	}
	b, err := s.BookByID(ctx, id)
	if err != nil {
		return err
	}
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)
	tag, err := tx.Exec(ctx, `UPDATE book_plan SET position=$1 WHERE position=$2`, b.Position, b.Position+delta)
	if err != nil {
		return err
	}
	if tag.RowsAffected() == 0 {
		return errors.New("already at the edge of the plan")
	}
	if _, err := tx.Exec(ctx, `UPDATE book_plan SET position=$2 WHERE id=$1`, id, b.Position+delta); err != nil {
		return err
	}
	return tx.Commit(ctx)
}

// MarkRead sets or clears the read flag of a book's summary.
func (s *Service) MarkRead(ctx context.Context, id int, done bool) error {
	var tag interface{ RowsAffected() int64 }
	var err error
	if done {
		tag, err = s.pool.Exec(ctx, `UPDATE book_summaries SET read_at=coalesce(read_at, now()) WHERE book_id=$1`, id)
	} else {
		tag, err = s.pool.Exec(ctx, `UPDATE book_summaries SET read_at=NULL WHERE book_id=$1`, id)
	}
	if err != nil {
		return err
	}
	if tag.RowsAffected() == 0 {
		return errors.New("this book has no summary yet")
	}
	return nil
}

// Reflect stores your rating (1 to 5, 0 = none) and note for a book.
func (s *Service) Reflect(ctx context.Context, id, rating int, note string) error {
	if rating < 0 || rating > 5 {
		return errors.New("rating must be 1 to 5")
	}
	var r *int
	if rating > 0 {
		r = &rating
	}
	tag, err := s.pool.Exec(ctx, `UPDATE book_summaries SET rating=$2, note=$3 WHERE book_id=$1`, id, r, strings.TrimSpace(note))
	if err == nil && tag.RowsAffected() == 0 {
		err = errors.New("this book has no summary yet")
	}
	return err
}

/* ---------- generation ---------- */

const systemPrompt = `You write detailed, faithful book summaries for one reader's daily learning plan. You explain the book's ideas thoroughly and accurately, in your own words, so the reader understands every important concept without reading the book.

Rules:
- Paraphrase. Never reproduce passages; quote at most a short phrase (under 15 words) and only when the exact wording matters.
- Be accurate about what the book actually says. If you are unsure about a detail, leave it out rather than invent it. Never invent studies, statistics or anecdotes and attribute them to the book.
- Distinguish clearly between established research, mixed evidence, the author's own framework, and contested or speculative claims.
- Examples must be concrete and realistic: software engineering and team work, and everyday life in India (family, friends, commuting, city life), not generic Western office cliches.
- No filler, no motivational fluff, no repetition between sections.
You answer only with the JSON that is asked for, no prose before or after.`

func (s *Service) context(ctx context.Context, b *Book, st Settings) string {
	var sb strings.Builder
	fmt.Fprintf(&sb, "BOOK SUMMARY, day %d of the plan.\n\nBook: %q by %s\n", b.Position, b.Title, b.Author)
	if b.Category != "" {
		fmt.Fprintf(&sb, "Category: %s\n", b.Category)
		if g := st.Categories[b.Category]; g != "" {
			fmt.Fprintf(&sb, "Category goal: %s\n", g)
		}
	}
	if b.Why != "" {
		fmt.Fprintf(&sb, "What the reader wants from it: %s\n", b.Why)
	}
	fmt.Fprintf(&sb, "\nREADER: %s\nPRIORITY: %s\nDEPTH: %s\nLANGUAGE: %s\n", st.Reader, st.Priority, st.Style, st.Language)
	return sb.String()
}

func (s *Service) earlier(ctx context.Context, position int) string {
	rows, err := s.pool.Query(ctx, `SELECT title, author FROM book_plan WHERE position < $1 ORDER BY position`, position)
	if err != nil {
		return ""
	}
	defer rows.Close()
	var list []string
	for rows.Next() {
		var t, a string
		if rows.Scan(&t, &a) == nil {
			list = append(list, fmt.Sprintf("%s (%s)", t, a))
		}
	}
	return strings.Join(list, "; ")
}

// Generate writes the summary of a book in two calls (introduction and lessons, then psychology,
// exercises and takeaways) and stores it, replacing any earlier one. Read state is kept.
func (s *Service) Generate(ctx context.Context, id int) (*Entry, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if !s.Configured() {
		return nil, errors.New("ANTHROPIC_API_KEY is not set")
	}
	b, err := s.BookByID(ctx, id)
	if err != nil {
		return nil, err
	}
	st := s.Settings(ctx)
	head := s.context(ctx, b, st)
	partA := st.Words * 3 / 5
	partB := st.Words - partA

	// part 1: introduction and core lessons
	var p1 struct {
		Intro   Intro    `json:"intro"`
		Lessons []Lesson `json:"lessons"`
	}
	prompt1 := head + fmt.Sprintf(`
PART 1 OF 2. Write about %d words in total for this part.

1. BOOK INTRODUCTION: the book in one sentence; what the author is trying to teach; who the author is and why they are credible; the central argument explained in 2 to 4 paragraphs; why it matters for this reader.
2. CORE LESSONS: the 10 to 15 most important concepts of the book, in the order the book builds them. For each: a clear title; the idea explained properly in 2 to 4 paragraphs (what it means, how the author argues it, the key distinctions); one concrete example at work (software engineering, team, career); one concrete example in everyday life in India; and one line to remember.

Use blank lines between paragraphs inside a text field.

Return ONLY this JSON:
{"intro":{"oneLine":"...","authorAim":"...","aboutAuthor":"...","bigIdea":"...","whoFor":"..."},
 "lessons":[{"title":"...","idea":"...","atWork":"...","inLife":"...","remember":"..."}]}`, partA)
	u1, err := s.llm.JSON(ctx, systemPrompt, prompt1, 14000, &p1)
	if err == nil {
		err = validate1(p1.Intro, p1.Lessons)
	}

	var p2 struct {
		Insights     []Insight  `json:"insights"`
		Exercises    []Exercise `json:"exercises"`
		Limits       string     `json:"limits"`
		Connections  []string   `json:"connections"`
		Takeaways    []string   `json:"takeaways"`
		FinalThought string     `json:"finalThought"`
	}
	var u2 llm.Usage
	if err == nil {
		titles := make([]string, len(p1.Lessons))
		for i, l := range p1.Lessons {
			titles[i] = fmt.Sprintf("%d. %s", i+1, l.Title)
		}
		earlier := s.earlier(ctx, b.Position)
		if earlier == "" {
			earlier = "(none, this is the first book)"
		}
		prompt2 := head + fmt.Sprintf(`
PART 2 OF 2. Part 1 (introduction and core lessons) is already written. Its lessons were:
%s

Write about %d words in total for this part. Do not repeat part 1; build on it.

3. PSYCHOLOGICAL INSIGHTS: 4 to 6 insights into WHY the book's ideas work (or fail): the mechanisms in human psychology, behaviour or society behind them. For each, say honestly what supports it: "established research", "mixed evidence", "author's framework" or "contested", and name the research area, researchers or tradition in "source" (no invented citations).
4. PRACTICAL IMPLEMENTATION: 5 to 7 exercises the reader can actually do, each with why it helps, 3 to 6 concrete steps, and when or how often (this week, daily for 2 weeks, before a meeting ...).
5. A CRITICAL VIEW: where the book is weak, dated, oversimplified or contested, and how to read it wisely (one or two paragraphs).
6. CONNECTIONS: 2 to 4 short links to books earlier in the reader's plan, only where the link is real. Earlier books: %s
7. FINAL TAKEAWAY: the 7 to 10 most important lessons to remember, one sentence each, then one closing paragraph.

Return ONLY this JSON:
{"insights":[{"title":"...","explanation":"...","evidence":"established research|mixed evidence|author's framework|contested","source":"..."}],
 "exercises":[{"title":"...","why":"...","steps":["...","..."],"when":"..."}],
 "limits":"...","connections":["..."],"takeaways":["..."],"finalThought":"..."}`, strings.Join(titles, "\n"), partB, earlier)
		u2, err = s.llm.JSON(ctx, systemPrompt, prompt2, 10000, &p2)
		if err == nil && (len(p2.Exercises) == 0 || len(p2.Takeaways) == 0) {
			err = errors.New("part 2 is missing exercises or takeaways")
		}
	}

	e := &Entry{Book: *b, Model: s.llm.Model, GeneratedAt: time.Now()}
	status := "ready"
	var sm Summary
	if err != nil {
		status, e.Error = "error", err.Error()
		log.Printf("summaries: %q: %v", b.Title, err)
	} else {
		sm = Summary{Intro: p1.Intro, Lessons: p1.Lessons, Insights: p2.Insights, Exercises: p2.Exercises, Limits: p2.Limits,
			Connections: p2.Connections, Takeaways: p2.Takeaways, FinalThought: p2.FinalThought}
		sm.WordCount = countWords(&sm)
		sm.Minutes = (sm.WordCount + 115) / 230
		e.Summary = &sm
		log.Printf("summaries: %q generated (%d words, %d lessons, %d in / %d out tokens)", b.Title, sm.WordCount, len(sm.Lessons),
			u1.InputTokens+u2.InputTokens, u1.OutputTokens+u2.OutputTokens)
	}
	e.Status = status
	raw, _ := json.Marshal(sm)
	if _, dbErr := s.pool.Exec(ctx, `INSERT INTO book_summaries(book_id,summary,model,status,error,generated_at) VALUES($1,$2,$3,$4,$5,now())
		ON CONFLICT (book_id) DO UPDATE SET summary=CASE WHEN EXCLUDED.status='ready' THEN EXCLUDED.summary ELSE book_summaries.summary END,
		model=EXCLUDED.model, status=CASE WHEN EXCLUDED.status='error' AND book_summaries.status='ready' THEN 'ready' ELSE EXCLUDED.status END,
		error=EXCLUDED.error, generated_at=CASE WHEN EXCLUDED.status='ready' THEN now() ELSE book_summaries.generated_at END`,
		id, raw, e.Model, status, e.Error); dbErr != nil {
		return nil, dbErr
	}
	if err != nil {
		return e, err
	}
	return e, nil
}

func validate1(in Intro, ls []Lesson) error {
	if strings.TrimSpace(in.BigIdea) == "" || strings.TrimSpace(in.AuthorAim) == "" {
		return errors.New("introduction is incomplete")
	}
	if len(ls) < 6 {
		return fmt.Errorf("model returned %d lessons, want 10 to 15", len(ls))
	}
	for i, l := range ls {
		if strings.TrimSpace(l.Title) == "" || len(strings.Fields(l.Idea)) < 40 {
			return fmt.Errorf("lesson %d is too thin", i+1)
		}
	}
	return nil
}

func countWords(sm *Summary) int {
	n := 0
	add := func(ss ...string) {
		for _, s := range ss {
			n += len(strings.Fields(s))
		}
	}
	add(sm.Intro.OneLine, sm.Intro.AuthorAim, sm.Intro.AboutAuthor, sm.Intro.BigIdea, sm.Intro.WhoFor, sm.Limits, sm.FinalThought)
	for _, l := range sm.Lessons {
		add(l.Title, l.Idea, l.AtWork, l.InLife, l.Remember)
	}
	for _, i := range sm.Insights {
		add(i.Title, i.Explanation, i.Source)
	}
	for _, x := range sm.Exercises {
		add(x.Title, x.Why, x.When)
		add(x.Steps...)
	}
	add(sm.Connections...)
	add(sm.Takeaways...)
	return n
}

/* ---------- scheduler ---------- */

// EnsureToday generates today's summary if missing or failed, and from 18:00 tomorrow's too.
// A ready summary is never regenerated here.
func (s *Service) EnsureToday(ctx context.Context) {
	if !s.Configured() {
		return
	}
	today := s.Today()
	days := []int{s.DayFor(ctx, today)}
	if time.Now().In(s.tz).Hour() >= 18 {
		days = append(days, days[0]+1)
	}
	for _, d := range days {
		if d < 1 {
			continue
		}
		b, err := s.BookAt(ctx, d)
		if err != nil || b.Status == "ready" {
			continue
		}
		if _, err := s.Generate(ctx, b.ID); err != nil {
			log.Printf("summaries: ensure day %d: %v", d, err)
		}
	}
}

// Paragraphs splits text on blank lines (for templates).
func Paragraphs(text string) []string {
	var out []string
	for _, p := range strings.Split(strings.ReplaceAll(text, "\r", ""), "\n\n") {
		if p = strings.TrimSpace(p); p != "" {
			out = append(out, p)
		}
	}
	return out
}
